package com.collapsechat;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.function.Consumer;

@Slf4j
@Singleton
public class ChatWidgetManager {
    @Inject
    private Client client;

    @Inject
    private CollapseChatConfig config;

    private static final String ORIGINAL_ALL_BUTTON_TEXT = "All";

    public void updateChatWidgets(ChatState state) {
        toggleChatButtonVisibility(state);
        updateAllButtonGraphic(state);
        updateButtonContent(state);
    }

    private void toggleChatButtonVisibility(ChatState state) {
        for (int buttonID : ChatButton.CONTAINER_IDS_TO_TOGGLE) {
            runOnWidgetIfPresent(buttonID, (Widget w) -> w.setHidden(state.isCollapsed()));
        }
    }

    private void updateAllButtonGraphic(ChatState state) {
        runOnWidgetIfPresent(ChatButton.ALL.graphicID, (Widget w) -> {
            boolean shouldBeTransparent = state.isCollapsed() && config.collapsedButtonTransparent();
            w.setOpacity(shouldBeTransparent ? 255 : 0);

            if (config.collapsedButtonTransparent()) {
                return;
            }

            w.setSpriteId(determineAllButtonSprite(state));
        });
    }

    private int determineAllButtonSprite(ChatState state) {
        if (state.isCollapsed()) {
            if (state.isMouseOverAllButton) {
                return SpriteID.ChatTabButton.HOVERED;
            }
            if (state.hasUnseenMessages) {
                return SpriteID.ChatTabButton.NEW_MESSAGES;
            }
        } else {
            if (state.selectedChatButton == ChatButton.ALL && state.isMouseOverAllButton) {
                return SpriteID.ChatTabButton.SELECTED_HOVERED;
            }
            if (state.selectedChatButton == ChatButton.ALL) {
                return SpriteID.ChatTabButton.SELECTED;
            }
            if (state.isMouseOverAllButton) {
                return SpriteID.ChatTabButton.HOVERED;
            }
        }
        return SpriteID.ChatTabButton.BUTTON;
    }

    public void setupMouseListeners(ChatState state, Runnable onStateChanged) {
        runOnWidgetIfPresent(ChatButton.ALL.containerID, (Widget allButton) -> {
            allButton.setOnMouseOverListener((JavaScriptCallback) ev -> {
                state.isMouseOverAllButton = true;
                onStateChanged.run();
            });
            allButton.setOnMouseLeaveListener((JavaScriptCallback) ev -> {
                state.isMouseOverAllButton = false;
                onStateChanged.run();
            });
            allButton.setHasListener(true);
        });
    }

    private void updateButtonContent(ChatState state) {
        if (state.collapseState != ChatCollapseState.COLLAPSED) {
            updateTextWidgetIfChanged(ChatButton.ALL.textID, ORIGINAL_ALL_BUTTON_TEXT);
            return;
        }

        String textToSet = ORIGINAL_ALL_BUTTON_TEXT;
        switch (config.collapsedButtonContent()) {
            case STATIC_TEXT:
                textToSet = state.isMouseOverAllButton
                        ? config.collapsedButtonContentCustomTextHovered()
                        : config.collapsedButtonContentCustomText();
                break;
            case REPORT_BUTTON_TEXT:
                Widget reportText = client.getWidget(ChatButton.REPORT.textID);
                if (reportText != null) {
                    textToSet = reportText.getText();
                }
                break;
        }
        updateTextWidgetIfChanged(ChatButton.ALL.textID, textToSet);
    }

    private void updateTextWidgetIfChanged(int textWidgetID, String newText) {
        runOnWidgetIfPresent(textWidgetID, (Widget w) -> {
            if (!w.getText().equals(newText)) {
                w.setText(newText);
            }
        });
    }

    public ChatButton getSelectedChatButton() {
        for (int buttonGraphicId : ChatButton.ALL_GRAPHIC_IDS) {
            Widget graphic = client.getWidget(buttonGraphicId);
            if (graphic == null || graphic.getSpriteId() == -1) {
                continue;
            }

            int sprite = graphic.getSpriteId();
            if (sprite == SpriteID.ChatTabButton.SELECTED || sprite == SpriteID.ChatTabButton.SELECTED_HOVERED) {
                return ChatButton.fromGraphicID(buttonGraphicId);
            }
        }
        return null;
    }

    private void runOnWidgetIfPresent(int widgetID, Consumer<Widget> action) {
        Widget w = client.getWidget(widgetID);
        if (w != null) {
            action.accept(w);
        }
    }
}

package com.collapsechat;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

import lombok.RequiredArgsConstructor;

@ConfigGroup(CollapseChatConfig.GROUP)
public interface CollapseChatConfig extends Config {
    String GROUP = "collapsechat";

    // 2. Enum for Logic (used for switch statements in Manager/Plugin)
    @RequiredArgsConstructor
    enum CollapsedButtonContent {
        STATIC_TEXT("Static text"),
        REPORT_BUTTON_TEXT("Report button text");

        private final String displayName;

        @Override
        public String toString() {
            return displayName;
        }
    }

    class Keys {
        public static final String CONTENT_TYPE = "collapsed-button-content";
        public static final String TRANSPARENT = "collapsed-button-transparent";

        public static final String STATIC_TEXT_SECTION = "static-text-section";
        public static final String CUSTOM_TEXT = "collapsed-button-content-text";
        public static final String CUSTOM_TEXT_HOVER = "collapsed-button-content-text-hovered";

        public static final String UNREAD_MESSAGE_SECTION = "report-button-section";
        public static final String HIGHLIGHT_ON_UNREAD_PUBLIC_CHAT_MESSAGES = "highlight-on-unread-public-messages";
        public static final String HIGHLIGHT_ON_UNREAD_PRIVATE_MESSAGES = "highlight-on-unread-private-messages";
        public static final String HIGHLIGHT_ON_UNREAD_CLAN_CHAT_MESSAGES = "highlight-on-unread-clanchat-messages";
        public static final String HIGHLIGHT_ON_UNREAD_FRIENDS_CHAT_MESSAGES = "highlight-on-unread-friendschat-messages";
        public static final String HIGHLIGHT_ON_UNREAD_TRADE_MESSAGES = "highlight-on-unread-trade-messages";
    }

    @ConfigItem(
            keyName = Keys.CONTENT_TYPE,
            name = "Button content",
            description = "Content to display in the collapsed chat button",
            position = 1
    )
    default CollapsedButtonContent collapsedButtonContent() {
        return CollapsedButtonContent.STATIC_TEXT;
    }

    @ConfigItem(
            keyName = Keys.TRANSPARENT,
            name = "Transparent button",
            description = "Make collapsed button transparent",
            position = 2
    )
    default boolean collapsedButtonTransparent() {
        return false;
    }

    @ConfigSection(
            name = "Static text",
            description = "Customize the static text shown on the collapsed chat button",
            position = 3,
            closedByDefault = true
    )
    String staticTextConfigSection = Keys.STATIC_TEXT_SECTION;

    @ConfigItem(
            keyName = Keys.CUSTOM_TEXT,
            name = "Button text",
            description = "Configure custom text for the collapsed chat button",
            position = 4,
            section = Keys.STATIC_TEXT_SECTION
    )
    default String collapsedButtonContentCustomText() {
        return "-";
    }

    @ConfigItem(
            keyName = Keys.CUSTOM_TEXT_HOVER,
            name = "Button text on hover",
            description = "Configure custom text for the collapsed chat button on mouse hover",
            position = 5,
            section = Keys.STATIC_TEXT_SECTION
    )
    default String collapsedButtonContentCustomTextHovered() {
        return "+";
    }

    @ConfigSection(
            name = "Highlight on unread messages",
            description = "Configure which types of unread chat messages highlight the button",
            position = 6,
            closedByDefault = true
    )
    String unreadMessagesSection = Keys.UNREAD_MESSAGE_SECTION;

    @ConfigItem(
            keyName = Keys.HIGHLIGHT_ON_UNREAD_PUBLIC_CHAT_MESSAGES,
            name = "Public",
            description = "Highlight button on unread public chat messages",
            position = 7,
            section = Keys.UNREAD_MESSAGE_SECTION
    )
    default boolean highlightOnUnreadPublicMessages() {
        return false;
    }

    @ConfigItem(
            keyName = Keys.HIGHLIGHT_ON_UNREAD_PRIVATE_MESSAGES,
            name = "Private",
            description = "Highlight button on unread private chat messages",
            position = 8,
            section = Keys.UNREAD_MESSAGE_SECTION
    )
    default boolean highlightOnUnreadPrivateMessages() {
        return false;
    }

    @ConfigItem(
            keyName = Keys.HIGHLIGHT_ON_UNREAD_FRIENDS_CHAT_MESSAGES,
            name = "Friends chat",
            description = "Highlight button on unread friends chat messages",
            position = 9,
            section = Keys.UNREAD_MESSAGE_SECTION
    )
    default boolean highlightOnUnreadFriendsChatMessages() {
        return false;
    }

    @ConfigItem(
            keyName = Keys.HIGHLIGHT_ON_UNREAD_CLAN_CHAT_MESSAGES,
            name = "Clan",
            description = "Highlight button on unread clan chat messages",
            position = 10,
            section = Keys.UNREAD_MESSAGE_SECTION
    )
    default boolean highlightOnUnreadClanChatMessages() {
        return false;
    }

    @ConfigItem(
            keyName = Keys.HIGHLIGHT_ON_UNREAD_TRADE_MESSAGES,
            name = "Trade",
            description = "Highlight button on unread trade chat messages",
            position = 11,
            section = Keys.UNREAD_MESSAGE_SECTION
    )
    default boolean highlightOnUnreadTradeMessages() {
        return false;
    }
}

package com.collapsechat;

import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.InterfaceID;

import java.util.Arrays;
import java.util.function.Predicate;

@RequiredArgsConstructor
public enum ChatButton {
    ALL(InterfaceID.Chatbox.CHAT_ALL, InterfaceID.Chatbox.CHAT_ALL_GRAPHIC, InterfaceID.Chatbox.CHAT_ALL_TEXT1, false),
    GAME(InterfaceID.Chatbox.CHAT_GAME, InterfaceID.Chatbox.CHAT_GAME_GRAPHIC, InterfaceID.Chatbox.CHAT_GAME_TEXT1, true),
    PUBLIC(InterfaceID.Chatbox.CHAT_PUBLIC, InterfaceID.Chatbox.CHAT_PUBLIC_GRAPHIC, InterfaceID.Chatbox.CHAT_PUBLIC_TEXT1, true),
    PRIVATE(InterfaceID.Chatbox.CHAT_PRIVATE, InterfaceID.Chatbox.CHAT_PRIVATE_GRAPHIC, InterfaceID.Chatbox.CHAT_PRIVATE_TEXT1, true),
    FRIENDS(InterfaceID.Chatbox.CHAT_FRIENDSCHAT, InterfaceID.Chatbox.CHAT_FRIENDSCHAT_GRAPHIC, InterfaceID.Chatbox.CHAT_FRIENDSCHAT_TEXT1, true),
    CLAN(InterfaceID.Chatbox.CHAT_CLAN, InterfaceID.Chatbox.CHAT_CLAN_GRAPHIC, InterfaceID.Chatbox.CHAT_CLAN_TEXT1, true),
    TRADE(InterfaceID.Chatbox.CHAT_TRADE, InterfaceID.Chatbox.CHAT_TRADE_GRAPHIC, InterfaceID.Chatbox.CHAT_TRADE_TEXT, true),
    REPORT(InterfaceID.Chatbox.REPORTABUSE, InterfaceID.Chatbox.REPORTABUSE_GRAPHIC, InterfaceID.Chatbox.REPORTABUSE_TEXT1, true);

    public final int containerID;
    public final int graphicID;
    public final int textID;
    public final boolean shouldToggle;

    public static final int[] CONTAINER_IDS_TO_TOGGLE;
    public static final int[] ALL_GRAPHIC_IDS;

    static {
        CONTAINER_IDS_TO_TOGGLE = Arrays.stream(values())
                .filter(button -> button.shouldToggle)
                .mapToInt(button -> button.containerID)
                .toArray();

        ALL_GRAPHIC_IDS = Arrays.stream(values())
                .mapToInt(button -> button.graphicID)
                .toArray();
    }

    public static ChatButton fromGraphicID(int graphicID) {
        return ChatButton.findOrNull(button -> button.graphicID == graphicID);
    }

    private static ChatButton findOrNull(Predicate<ChatButton> predicate) {
        return Arrays.stream(values())
                .filter(predicate)
                .findFirst()
                .orElse(null);
    }
}

package com.collapsechat;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.VarClientIntChanged;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;

import javax.inject.Inject;
import java.time.temporal.ChronoUnit;


@Slf4j
@PluginDescriptor(
        name = "Collapse Chat",
        description = "Collapse chat to a single button when minimized",
        tags = {"chat", "collapse", "ui"}
)
public class CollapseChatPlugin extends Plugin {
    @Inject
    private Client client;
    @Inject
    private ClientThread clientThread;
    @Inject
    private ChatWidgetManager widgetManager;

    private final ChatState state = new ChatState();

    @Provides
    CollapseChatConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(CollapseChatConfig.class);
    }

    @Inject
    private CollapseChatConfig config;

    @Override
    protected void startUp() {
        state.reset();
        clientThread.invokeLater(this::refreshAll);
    }

    @Override
    protected void shutDown() {
        state.reset();
        clientThread.invokeLater(() -> {
            refreshChatWidgets();

            // We need to run script 113 to reset the on-hover behavior for the
            // all button which breaks because we override the mouse event listeners
            client.runScript(113);
        });
    }

    private void refreshAll() {
        widgetManager.setupMouseListeners(state, this::refreshChatWidgets);
        updateChatState();
        refreshChatWidgets();
    }

    private void refreshChatWidgets() {
        widgetManager.updateChatWidgets(state);
    }

    @Subscribe
    void onScriptPostFired(ScriptPostFired event) {
        if (event.getScriptId() == ScriptID.CHAT_PROMPT_INIT) {
            refreshAll();
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (!"Switch tab".equals(event.getMenuOption())) return;

        clientThread.invokeLater(() -> {
            updateChatState();
            refreshChatWidgets();
        });
    }

    @Subscribe
    void onVarClientIntChanged(VarClientIntChanged event) {
        if (event.getIndex() == VarClientID.CHAT_LASTREBUILD) {
            refreshAll();
        }
    }

    @Subscribe
    void onConfigChanged(ConfigChanged event) {
        if (CollapseChatConfig.GROUP.equals(event.getGroup())) {
            clientThread.invokeLater(this::refreshChatWidgets);
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (state.isCollapsed()) {
            if (isSubscribedToChatMessageType(event.getType())) {
                state.hasUnseenMessages = true;
            }
        }
        clientThread.invokeLater(this::refreshChatWidgets);
    }

    @Schedule(period = 500, unit = ChronoUnit.MILLIS)
    public void reportTextPoller() {
        if (config.collapsedButtonContent() == CollapseChatConfig.CollapsedButtonContent.REPORT_BUTTON_TEXT) {
            clientThread.invokeLater(this::refreshChatWidgets);
        }
    }

    private boolean isUsingSplitPrivateChat() {
        return client.getVarpValue(VarPlayerID.OPTION_PM) == 1;
    }

    private boolean isPrivateChatHiddenWithChat() {
        return client.getVarbitValue(VarbitID.HIDE_PM_ALONGSIDE_CHATBOX) == 1;
    }

    private boolean arePrivateMessagesHiddenOnCollapse() {
        return !isUsingSplitPrivateChat() || isPrivateChatHiddenWithChat();
    }

    private boolean isSubscribedToChatMessageType(ChatMessageType messageType) {
        switch (messageType) {
            case PUBLICCHAT:
                return config.highlightOnUnreadPublicMessages();
            case PRIVATECHAT:
                return config.highlightOnUnreadPrivateMessages() && arePrivateMessagesHiddenOnCollapse();
            case CLAN_CHAT:
                return config.highlightOnUnreadClanChatMessages();
            case TRADE:
                return config.highlightOnUnreadTradeMessages();
            case FRIENDSCHAT:
                return config.highlightOnUnreadFriendsChatMessages();
            default:
                return false;
        }
    }

    private void updateChatState() {
        state.selectedChatButton = widgetManager.getSelectedChatButton();
        if (state.selectedChatButton == null) {
            state.collapseState = ChatCollapseState.COLLAPSED;
        } else {
            state.collapseState = ChatCollapseState.EXPANDED;
            state.hasUnseenMessages = false;
        }
    }
}

package com.collapsechat;

public class ChatState {
    public ChatCollapseState collapseState = ChatCollapseState.UNKNOWN;
    public boolean isMouseOverAllButton = false;
    public boolean hasUnseenMessages = false;
    ChatButton selectedChatButton = null;

    public void reset() {
        this.collapseState = ChatCollapseState.UNKNOWN;
        this.isMouseOverAllButton = false;
        this.hasUnseenMessages = false;
        this.selectedChatButton = null;
    }

    public boolean isCollapsed() {
        return collapseState == ChatCollapseState.COLLAPSED;
    }
}
